import React from "react";

function About() {
  return (
    <div className="about">
      <div class="container">
        <div class="row align-items-center my-5">
          <div class="col-lg-5">
            <h1 class="font-weight-light">What would you like to inquire?</h1>
            <p>
              Add question form here
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default About;
